&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1123&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT\n    d.*,\n    s.Nume,\n    COALESCE\n    (\n        tip.Denumire,\n        CONVERT(NVARCHAR(50), d.FelPersoana)\n    ) AS DenumireTipPersoana,\n    CASE\n        WHEN d.Grad IS NULL THEN &#39;Fara grad&#39;\n        ELSE CONCAT(&#39;Grad &#39;, d.Grad)\n    END AS DenumireGrad\nFROM app.PersoanaIntretinere d\nINNER JOIN app.Salariat s\n    ON d.CodSucursala = s.CodSucursala\n   AND d.Marca = s.Marca\nOUTER APPLY\n(\n    SELECT MAX(tp.Denumire) AS Denumire\n    FROM app.TipPersoana tp\n    WHERE tp.Anul = @Anul\n      AND tp.FelPersoana = d.FelPersoana\n) tip\nWHERE d.CodSucursala = @CodSucursala\nORDER BY\n    d.Marca,\n    d.FelPersoana,\n    d.DataNasteriiCopil;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;AltProcent&quot;,&quot;Name&quot;:&quot;AltProcent&quot;,&quo